SELECT courier_id AS courierId, count(*) AS count FROM cc_pickup_dispatch_task WHERE courier_id IN
#{courierId}
AND task_type = #{type} AND ( (status = 1 AND estimated_end_time BETWEEN #{startDateTime} AND #{endDateTime}) OR (status = 2 AND actual_end_time BETWEEN #{startDateTime} AND #{endDateTime}) OR (status = 3 AND cancel_time BETWEEN #{startDateTime} AND #{endDateTime}) ) GROUP BY courier_id
